using System;
using System.ComponentModel;
using System.Diagnostics;
using EnumsNET;
using LanguageExt;

namespace SJP.Schematic.Core;

/// <summary>
/// Describes where the values of a column come from: written by whoever inserts or updates a row,
/// computed by the database from an expression, or generated by the database as an identity.
/// </summary>
/// <remarks>
/// <para>
/// A column is exactly one of these. No supported database allows a column to be both computed and
/// an identity, so a column that is computed has no identity to describe, and an identity column has
/// no expression. Switch on the value source to reach what only one of them has, such as the
/// <see cref="Computed.Definition"/> of a computed column or the <see cref="Generated.Identity"/> of
/// an identity column.
/// </para>
/// <para>
/// A column's default is described separately, by <see cref="IDatabaseColumn.Default"/>, as a
/// <see cref="Stored"/> column may have one too.
/// </para>
/// <para>
/// Each case has value equality, so two value sources that describe the same thing compare equal.
/// A <see langword="default"/> value holds no value source.
/// </para>
/// </remarks>
[DebuggerDisplay("{" + nameof(ToString) + "(),nq}")]
public readonly union ColumnValueSource(
    ColumnValueSource.Stored,
    ColumnValueSource.Computed,
    ColumnValueSource.Generated
)
{
    /// <summary>
    /// Returns a string that provides a basic string representation of this object.
    /// </summary>
    /// <returns>A <see cref="string"/> that represents this instance.</returns>
    [EditorBrowsable(EditorBrowsableState.Never)]
    public override string ToString() => Value?.ToString() ?? string.Empty;

    /// <summary>
    /// The values of the column are those written to it, or its default when a row omits it. This is
    /// an ordinary column.
    /// </summary>
    public sealed record Stored;

    /// <summary>
    /// The values of the column are computed by the database from an expression, e.g. a SQL Server
    /// computed column, an Oracle virtual column, or a PostgreSQL, MySQL or SQLite generated column.
    /// </summary>
    public sealed record Computed
    {
        /// <summary>
        /// Initializes a new instance of the <see cref="Computed"/> class.
        /// </summary>
        /// <param name="definition">The expression that computes the values of the column, if available.</param>
        /// <param name="storage">Whether the computed values are stored or evaluated when read.</param>
        /// <exception cref="ArgumentException"><paramref name="storage"/> is not a valid enum value.</exception>
        public Computed(Option<string> definition, ComputedColumnStorage storage)
        {
            if (!storage.IsValid())
                throw new ArgumentException($"The {nameof(ComputedColumnStorage)} provided must be a valid enum.", nameof(storage));

            Definition = definition;
            Storage = storage;
        }

        /// <summary>
        /// The expression that computes the values of the column. Optional, as some providers (e.g.
        /// Oracle) allow the definition to be missing.
        /// </summary>
        /// <value>A computed column definition, if available.</value>
        public Option<string> Definition { get; }

        /// <summary>
        /// Whether the computed values of the column are stored in the table or evaluated when the
        /// column is read.
        /// </summary>
        /// <value>The storage applied to the computed column.</value>
        public ComputedColumnStorage Storage { get; }
    }

    /// <summary>
    /// The values of the column are generated by the database when a row is inserted, e.g. an
    /// identity, serial, <c>AUTO_INCREMENT</c> or SQLite rowid alias column.
    /// </summary>
    public sealed record Generated
    {
        /// <summary>
        /// Initializes a new instance of the <see cref="Generated"/> class.
        /// </summary>
        /// <param name="identity">The parameters of the sequence generating the column's values.</param>
        /// <exception cref="ArgumentNullException"><paramref name="identity"/> is <see langword="null" />.</exception>
        public Generated(IAutoIncrement identity)
        {
            Identity = identity ?? throw new ArgumentNullException(nameof(identity));
        }

        /// <summary>
        /// The parameters of the sequence generating the column's values.
        /// </summary>
        /// <value>An automatic increment definition.</value>
        public IAutoIncrement Identity { get; }
    }
}
